function formatMoment(value: string | null): string {
	if (!value) return "тАФ";
	const parsed = new Date(value);
	return Number.isNaN(parsed.getTime())
		? "тАФ"
		: parsed.toLocaleString("ru-RU", {
				day: "2-digit",
				month: "2-digit",
				hour: "2-digit",
				minute: "2-digit",
			});
}

