	/**
	 * GET /api/communications/campaigns/:id/progress тАФ ╨╡╨┤╨╕╨╜╤Б╤В╨▓╨╡╨╜╨╜╤Л╨╣ ╤Б╨┐╨╛╤Б╨╛╨▒ ╤Г╨▓╨╕╨┤╨╡╤В╤М
	 * ┬л╤Б╨║╨╛╨╗╤М╨║╨╛ ╤Г╤И╨╗╨╛ / ╤Б╨║╨╛╨╗╤М╨║╨╛ ╨╖╨░╨▓╨╕╤Б╨╗╨╛┬╗ ╨▒╨╡╨╖ ╤А╤Г╤З╨╜╨╛╨│╨╛ ╤Д╨╕╨╗╤М╤В╤А╨░ ╨╢╤Г╤А╨╜╨░╨╗╨░ ╨╛╤З╨╡╤А╨╡╨┤╨╕.
	 * ╨а╨░╨╜╤М╤И╨╡ ╨╝╨░╤А╤И╤А╤Г╤В ╨╢╨╕╨╗ ╨╜╨░ API, ╨░ ╨▓╨╡╨▒ ╨╡╨│╨╛ ╨╜╨╕ ╤А╨░╨╖╤Г ╨╜╨╡ ╨▓╤Л╨╖╤Л╨▓╨░╨╗.
	 */
	const loadProgress = useCallback(
		async (campaignId: string) => {
			setProgressFor(campaignId);
			setProgressLoading(true);
			setProgressError(null);
			try {
				const response = await commQueries.getCampaignProgress(campaignId);
				const data = await readJson<{
