				showToast(
					actionFailureToast(
						"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
						(error as { status?: number })?.status ?? null,
					),
					"error",
				);
				setProgress(null);
				setProgressError(
					error instanceof Error ? error.message : String(error),
				);
			} finally {
				setProgressLoading(false);
			}
		},
		[commQueries.getCampaignProgress],
	);

	// ╨Я╨╛╨║╨░ ╤А╨░╤Б╤Б╤Л╨╗╨║╨░ ┬л╨Т╤Л╨┐╨╛╨╗╨╜╤П╨╡╤В╤Б╤П┬╗ ╨╕ ╨╛╤В╨║╤А╤Л╤В ╨╡╤С ╤Е╨╛╨┤ тАФ ╨╛╨┐╤А╨░╤И╨╕╨▓╨░╤В╤М, ╨╕╨╜╨░╤З╨╡ ╤Ж╨╕╤Д╤А╤Л
	// ╨╖╨░╤Б╤В╤Л╨▓╨░╤О╤В ╨┐╨╛╤Б╨╗╨╡ ╨┐╨╡╤А╨▓╨╛╨│╨╛ ╨╖╨░╨┐╤А╨╛╤Б╨░, ╨░ ╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╤П ╨┐╤А╨╛╨┤╨╛╨╗╨╢╨░╤О╤В ╤Г╤Е╨╛╨┤╨╕╤В╤М.
	useEffect(() => {
		if (!progressFor) return;
		const row = campaigns.find((c) => c.id === progressFor);
		if (row?.status !== "running") return;
		const timer = window.setInterval(() => {
			void loadProgress(progressFor);
		}, 8000);
		return () => window.clearInterval(timer);
	}, [progressFor, campaigns, loadProgress]);

