import cornerstoneDICOMImageLoader from "@cornerstonejs/dicom-image-loader";
import * as fflate from "fflate";
import type React from "react";
import { useCallback, useState } from "react";
import { actionFailureToast } from "../../lib/panelStateText";
import { showToast } from "../GlobalToast";

interface DicomArchiveUploaderProps {
	onImagesLoaded: (imageIds: string[]) => void;
}

export function DicomArchiveUploader({
	onImagesLoaded,
}: DicomArchiveUploaderProps) {
	const [isDragging, setIsDragging] = useState(false);
	const [loading, setLoading] = useState(false);
	const [status, setStatus] = useState<string>(
		"╨Я╨╡╤А╨╡╤В╨░╤Й╨╕╤В╨╡ ZIP-╨░╤А╤Е╨╕╨▓ ╨╕╨╗╨╕ ╨┐╨░╨┐╨║╤Г ╤Б╨╛ ╤Б╨╜╨╕╨╝╨║╨░╨╝╨╕ ╤Б╤О╨┤╨░",
	);

	const processFile = useCallback(
		async (file: File): Promise<string | null> => {
			return new Promise((resolve) => {
				const reader = new FileReader();
				reader.onload = () => {
					try {
						const arrayBuffer = reader.result as ArrayBuffer;
						const byteArray = new Uint8Array(arrayBuffer);

						// Check DICOM magic number at offset 128
						if (byteArray.length < 132) {
							resolve(null);
							return;
						}

						const dicmPrefix = String.fromCharCode(
							byteArray[128] ?? 0,
							byteArray[129] ?? 0,
							byteArray[130] ?? 0,
							byteArray[131] ?? 0,
						);
						if (dicmPrefix !== "DICM") {
							resolve(null);
							return;
						}

						// Generate imageId using cornerstone wado-uri fileManager
						const imageId =
							cornerstoneDICOMImageLoader.wadouri.fileManager.add(file);
						resolve(imageId);
					} catch (e) {
						showToast(
							actionFailureToast(
								"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
								(e as { status?: number })?.status ?? null,
							),
							"error",
						);
						console.error("Failed to parse file", file.name, e);
						resolve(null);
					}
				};
				reader.onerror = () => resolve(null);
				reader.readAsArrayBuffer(file.slice(0, 1024)); // Only read first 1KB for DICM check
			});
		},
		[],
	);

	const MAX_SAFE_FILE_SIZE_BYTES = 1.5 * 1024 * 1024 * 1024; // 1.5 GB

	const processZip = useCallback(
		async (zipFile: File) => {
			if (zipFile.size > MAX_SAFE_FILE_SIZE_BYTES) {
				setStatus(
					"╨д╨░╨╣╨╗ ╤Б╨╗╨╕╤И╨║╨╛╨╝ ╨▓╨╡╨╗╨╕╨║ ╨┤╨╗╤П ╨╛╨▒╤А╨░╨▒╨╛╤В╨║╨╕ ╨▓ ╨┐╨░╨╝╤П╤В╨╕ ╨▒╤А╨░╤Г╨╖╨╡╤А╨░. ╨Ш╤Б╨┐╨╛╨╗╤М╨╖╤Г╨╣╤В╨╡ ╨┐╤А╨╛╤Б╨╝╨╛╤В╤А ╨┐╨╛ ╤Б╤А╨╡╨╖╨░╨╝.",
				);
				return;
			}

			setStatus("╨а╨░╤Б╨┐╨░╨║╨╛╨▓╨║╨░ ZIP-╨░╤А╤Е╨╕╨▓╨░ ╨▓ ╨┐╨░╨╝╤П╤В╤М...");
			const buffer = new Uint8Array(await zipFile.arrayBuffer());

			return new Promise<void>((resolve, reject) => {
				const imageIds: string[] = [];
				let totalFiles = 0;
				let processedFiles = 0;

				fflate.unzip(buffer, (err, unzipped) => {
					if (err) {
						reject(err);
						return;
					}

					const entries = Object.keys(unzipped);
					totalFiles = entries.length;

					const processEntry = async (index: number) => {
						if (index >= entries.length) {
							if (imageIds.length > 0) {
								setStatus(`╨Ч╨░╨│╤А╤Г╨╢╨╡╨╜╨╛ ╨╛╨▒╤К╨╡╨║╤В╨╛╨▓ DICOM: ${imageIds.length}`);
								onImagesLoaded(imageIds);
							} else {
								setStatus("╨д╨░╨╣╨╗╤Л DICOM ╨▓ ZIP-╨░╤А╤Е╨╕╨▓╨╡ ╨╜╨╡ ╨╜╨░╨╣╨┤╨╡╨╜╤Л.");
							}
							resolve();
							return;
						}

						const filename = entries[index]!;
						const fileData = unzipped[filename];
						processedFiles++;

						if (processedFiles % 10 === 0) {
							setStatus(`╨Ю╨▒╤А╨░╨▒╨╛╤В╨║╨░ ZIP: ${processedFiles}/${totalFiles}`);
						}

						if (fileData && fileData.length > 132) {
							const dicmPrefix = String.fromCharCode(
								fileData[128] ?? 0,
								fileData[129] ?? 0,
								fileData[130] ?? 0,
								fileData[131] ?? 0,
							);
							if (dicmPrefix === "DICM") {
								const file = new File([fileData], filename);
								const imageId =
									cornerstoneDICOMImageLoader.wadouri.fileManager.add(file);
								imageIds.push(imageId);
							}
						}

						setTimeout(() => processEntry(index + 1), 0);
					};

					processEntry(0);
				});
			});
		},
		[onImagesLoaded],
	);

	const traverseFileTree = useCallback(
		async (item: any, path: string = ""): Promise<File[]> => {
			return new Promise((resolve) => {
				if (item.isFile) {
					item.file((file: File) => {
						resolve([file]);
					});
				} else if (item.isDirectory) {
					// ╨С╨л╨Ы╨Ю: readEntries ╨▓╤Л╨╖╤Л╨▓╨░╨╗╤Б╤П ╨Ю╨Ф╨Ш╨Э ╤А╨░╨╖. ╨Я╨╛ ╤Б╨┐╨╡╤Ж╨╕╤Д╨╕╨║╨░╤Ж╨╕╨╕ FileSystem API ╨╛╨╜
					// ╨╛╤В╨┤╨░╤С╤В ╨╜╨╡ ╨▒╨╛╨╗╤М╤И╨╡ ~100 ╨╖╨░╨┐╨╕╤Б╨╡╨╣ ╨╖╨░ ╨▓╤Л╨╖╨╛╨▓ ╨╕ ╤В╤А╨╡╨▒╤Г╨╡╤В ╨┐╨╛╨▓╤В╨╛╤А╨╜╤Л╤Е ╨▓╤Л╨╖╨╛╨▓╨╛╨▓,
					// ╨┐╨╛╨║╨░ ╨╜╨╡ ╨▓╨╡╤А╨╜╤С╤В ╨┐╤Г╤Б╤В╨╛╨╣ ╨╝╨░╤Б╤Б╨╕╨▓. ╨Я╨░╨┐╨║╨░ ╨Ъ╨Ы╨Ъ╨в ╨╜╨░ 400 ╤Б╤А╨╡╨╖╨╛╨▓ ╨╖╨░╨│╤А╤Г╨╢╨░╨╗╨░╤Б╤М
					// ╨╜╨░ 100 ╤Д╨░╨╣╨╗╨╛╨▓, ╤А╨╡╨║╨╛╨╜╤Б╤В╤А╤Г╨║╤Ж╨╕╤П ╤Б╤В╤А╨╛╨╕╨╗╨░╤Б╤М ╨┐╨╛ ╨╜╨╡╨┐╨╛╨╗╨╜╨╛╨╣ ╤З╨╡╨╗╤О╤Б╤В╨╕,
					// ╨░ ╤Б╤В╨░╤В╤Г╤Б ╨▒╨╛╨┤╤А╨╛ ╤Б╨╛╨╛╨▒╤Й╨░╨╗ ┬л╨Ч╨░╨│╤А╤Г╨╢╨╡╨╜╨╛ ╨╛╨▒╤К╨╡╨║╤В╨╛╨▓ DICOM: 100┬╗.
					const dirReader = item.createReader();
					const files: File[] = [];
					const readBatch = () => {
						dirReader.readEntries(
							async (entries: any[]) => {
								if (!entries || entries.length === 0) {
									resolve(files);
									return;
								}
								for (let i = 0; i < entries.length; i++) {
									const nestedFiles = await traverseFileTree(
										entries[i],
										`${path + item.name}/`,
									);
									files.push(...nestedFiles);
								}
								readBatch();
							},
							() => resolve(files),
						);
					};
					readBatch();
				} else {
					resolve([]);
				}
			});
		},
		[],
	);

	const onDrop = useCallback(
		async (e: React.DragEvent<HTMLElement>) => {
			e.preventDefault();
			setIsDragging(false);

			if (loading) return;
			setLoading(true);

			// ╨С╨л╨Ы╨Ю: ╤В╨╡╨╗╨░ ╨╛╨▒╤А╨░╨▒╨╛╤В╤З╨╕╨║╨░ ╨▒╨╡╨╖ try/catch. ╨Х╤Б╨╗╨╕ processZip ╨┐╨░╨┤╨░╨╗ ╨╜╨░ ╨▒╨╕╤В╨╛╨╝ ╨╕╨╗╨╕
			// ╨╖╨░╤И╨╕╤Д╤А╨╛╨▓╨░╨╜╨╜╨╛╨╝ ╨░╤А╤Е╨╕╨▓╨╡, setLoading(false) ╨▓ ╨║╨╛╨╜╤Ж╨╡ ╨╜╨╡ ╨▓╤Л╨┐╨╛╨╗╨╜╤П╨╗╤Б╤П: ╨║╤А╤Г╤В╨╕╨╗╨║╨░
			// ╨▓╨╕╤Б╨╡╨╗╨░ ╨▓╨╡╤З╨╜╨╛, ╤Б╤В╨░╤В╤Г╤Б ╨╖╨░╨╝╨╕╤А╨░╨╗ ╨╜╨░ ┬л╨а╨░╤Б╨┐╨░╨║╨╛╨▓╨║╨░ ZIP-╨░╤А╤Е╨╕╨▓╨░ ╨▓ ╨┐╨░╨╝╤П╤В╤М...┬╗,
			// ╨░ ╨┐╤А╨╛╨▓╨╡╤А╨║╨░ `if (loading) return` ╨▒╨╗╨╛╨║╨╕╤А╨╛╨▓╨░╨╗╨░ ╨▓╤Б╨╡ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╕╨╡ ╨┐╨╛╨┐╤Л╤В╨║╨╕.
			// ╨Ч╨░╨│╤А╤Г╨╖╤З╨╕╨║ ╤Г╨╝╨╕╤А╨░╨╗ ╨┤╨╛ ╨┐╨╡╤А╨╡╨╖╨░╨│╤А╤Г╨╖╨║╨╕ ╤Б╤В╤А╨░╨╜╨╕╤Ж╤Л, ╨╕ ╨▓╤А╨░╤З ╨╜╨╡ ╨▓╨╕╨┤╨╡╨╗ ╨┐╤А╨╕╤З╨╕╨╜╤Л.
			try {
				const items = e.dataTransfer.items;
				let allFiles: File[] = [];

				setStatus("╨з╤В╨╡╨╜╨╕╨╡ ╨▓╤Л╨▒╤А╨░╨╜╨╜╤Л╤Е ╤Д╨░╨╣╨╗╨╛╨▓...");

				if (items && items.length > 0) {
					for (let i = 0; i < items.length; i++) {
						const item = items[i]?.webkitGetAsEntry();
						if (item) {
							const files = await traverseFileTree(item);
							allFiles = allFiles.concat(files);
						}
					}
				} else if (e.dataTransfer.files) {
					allFiles = Array.from(e.dataTransfer.files);
				}

				const firstFile = allFiles[0];
				if (
					allFiles.length === 1 &&
					firstFile &&
					firstFile.name.toLowerCase().endsWith(".zip")
				) {
					await processZip(firstFile);
				} else {
					setStatus(`╨б╨║╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡ ╤Д╨░╨╣╨╗╨╛╨▓: ${allFiles.length}...`);
					const validImageIds: string[] = [];

					for (let i = 0; i < allFiles.length; i++) {
						if (i % 10 === 0)
							setStatus(`╨б╨║╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡ ╤Д╨░╨╣╨╗╨╛╨▓: ${i}/${allFiles.length}`);
						const f = allFiles[i];
						if (f) {
							const imageId = await processFile(f);
							if (imageId) validImageIds.push(imageId);
						}
					}

					if (validImageIds.length > 0) {
						setStatus(`╨Ч╨░╨│╤А╤Г╨╢╨╡╨╜╨╛ ╨╛╨▒╤К╨╡╨║╤В╨╛╨▓ DICOM: ${validImageIds.length}`);
						onImagesLoaded(validImageIds);
					} else {
						setStatus("╨Я╨╛╨┤╤Е╨╛╨┤╤П╤Й╨╕╨╡ ╤Д╨░╨╣╨╗╤Л DICOM ╨╜╨╡ ╨╜╨░╨╣╨┤╨╡╨╜╤Л.");
					}
				}
			} catch (error) {
				showToast(
					actionFailureToast(
						"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
						(error as { status?: number })?.status ?? null,
					),
					"error",
				);
				console.error("[DicomArchiveUploader] ╨Ю╤И╨╕╨▒╨║╨░ ╨╛╨▒╤А╨░╨▒╨╛╤В╨║╨╕:", error);
				setStatus(
					"╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨┐╤А╨╛╤З╨╕╤В╨░╤В╤М ╤Д╨░╨╣╨╗╤Л: ╨░╤А╤Е╨╕╨▓ ╨┐╨╛╨▓╤А╨╡╨╢╨┤╤С╨╜, ╨╖╨░╤И╨╕╤Д╤А╨╛╨▓╨░╨╜ ╨╕╨╗╨╕ ╨╜╨╡ ╤Б╨╛╨┤╨╡╤А╨╢╨╕╤В DICOM. ╨Я╨╛╨┐╤А╨╛╨▒╤Г╨╣╤В╨╡ ╨┤╤А╤Г╨│╨╛╨╣ ╨░╤А╤Е╨╕╨▓ ╨╕╨╗╨╕ ╤А╨░╤Б╨┐╨░╨║╤Г╨╣╤В╨╡ ╨╡╨│╨╛ ╨▓╤А╤Г╤З╨╜╤Г╤О.",
				);
			} finally {
				setLoading(false);
			}
		},
		[loading, onImagesLoaded, traverseFileTree, processZip, processFile],
	);

	return (
		<button
			type="button"
			aria-label="╨Ч╨╛╨╜╨░ ╨╖╨░╨│╤А╤Г╨╖╨║╨╕ DICOM"
			onDragOver={(e) => {
				e.preventDefault();
				setIsDragging(true);
			}}
			onDragLeave={() => setIsDragging(false)}
			onDrop={onDrop}
			onClick={() => document.getElementById("dicom-folder-input")?.click()}
			onKeyDown={(e) => {
				if (e.key === "Enter" || e.key === " ") {
					e.preventDefault();
					document.getElementById("dicom-folder-input")?.click();
				}
			}}
			className={`w-full h-32 flex flex-col items-center justify-center border-2 border-dashed rounded-lg transition-colors cursor-pointer bg-transparent ${
				isDragging
					? "border-teal-500 bg-teal-500/10"
					: "border-slate-300 dark:border-neutral-700 bg-slate-50 dark:bg-neutral-900 hover:bg-slate-100 dark:hover:bg-neutral-800"
			}`}
		>
			<input
				id="dicom-folder-input"
				type="file"
				webkitdirectory="true"
				directory="true"
				multiple
				style={{ display: "none" }}
				onChange={async (e) => {
					if (loading || !e.target.files) return;
					setLoading(true);
					const allFiles = Array.from(e.target.files);
					setStatus(`╨б╨║╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡ ╤Д╨░╨╣╨╗╨╛╨▓: ${allFiles.length}...`);
					const validImageIds: string[] = [];
					for (let i = 0; i < allFiles.length; i++) {
						if (i % 10 === 0)
							setStatus(`╨б╨║╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡ ╤Д╨░╨╣╨╗╨╛╨▓: ${i}/${allFiles.length}`);
						const f = allFiles[i];
						if (f) {
							const imageId = await processFile(f);
							if (imageId) validImageIds.push(imageId);
						}
					}
					if (validImageIds.length > 0) {
						setStatus(`╨Ч╨░╨│╤А╤Г╨╢╨╡╨╜╨╛ ╨╛╨▒╤К╨╡╨║╤В╨╛╨▓ DICOM: ${validImageIds.length}`);
						onImagesLoaded(validImageIds);
					} else {
						setStatus("╨Я╨╛╨┤╤Е╨╛╨┤╤П╤Й╨╕╨╡ ╤Д╨░╨╣╨╗╤Л DICOM ╨╜╨╡ ╨╜╨░╨╣╨┤╨╡╨╜╤Л.");
					}
					setLoading(false);
					// reset input
					e.target.value = "";
				}}
			/>
			<div className="text-slate-700 dark:text-neutral-300 font-medium">
				{status} (╨Ъ╨╗╨╕╨║╨╜╨╕╤В╨╡ ╨┤╨╗╤П ╨▓╤Л╨▒╨╛╤А╨░ ╨╕╨╗╨╕ ╨┐╨╡╤А╨╡╤В╨░╤Й╨╕╤В╨╡ ╨┐╨░╨┐╨║╤Г)
			</div>
			{loading && (
				<div className="mt-2 w-6 h-6 border-2 border-teal-500 border-t-transparent rounded-full animate-spin"></div>
			)}
			<div className="text-xs text-slate-500 dark:text-neutral-500 mt-2">
				╨Ы╨╛╨║╨░╨╗╤М╨╜╨░╤П ╨╛╨▒╤А╨░╨▒╨╛╤В╨║╨░ ╨▓ ╨▒╤А╨░╤Г╨╖╨╡╤А╨╡. ╨Ф╨░╨╜╨╜╤Л╨╡ ╨╜╨╡ ╨┐╨╡╤А╨╡╨┤╨░╤О╤В╤Б╤П ╨╜╨░ ╤Б╤В╨╛╤А╨╛╨╜╨╜╨╕╨╡
				╤Б╨╡╤А╨▓╨╡╤А╨░.
			</div>
		</button>
	);
}

