function SourcePanel(props: {
	busy: boolean;
	allowLlm: boolean;
	onAllowLlmChange: (value: boolean) => void;
	fileInputRef: React.MutableRefObject<HTMLInputElement | null>;
	onFile: (file: File) => void;
