						<div className="mw-proj-item">
							<span className="mw-proj-value">
								{mapping.mapping.columns.length}
							</span>
							<span className="mw-proj-label">╨║╨╛╨╗╨╛╨╜╨╛╨║ ╤Б╨╛╨┐╨╛╤Б╤В╨░╨▓╨╗╨╡╨╜╨╛</span>
						</div>
						{mapping.llm.calls > 0 && (
