																	</span>
																) : null}
																{byGrant && on ? (
																	<span className="text-xs text-emerald-700 dark:text-emerald-300 block mt-0.5">
																		╨Т╤Л╨┤╨░╨╜╨╛ ╨┐╨╡╤А╤Б╨╛╨╜╨░╨╗╤М╨╜╨╛ (╨╜╨░╨┤╨▒╨░╨▓╨║╨░ ╨║ ╤А╨╛╨╗╨╕).
																	</span>
																) : null}
															</span>
														</label>
													);
												})}
											</div>
										</div>
									) : null}
								</li>
							);
						})}
					</ul>
				) : null}

				{save.kind === "failed" ? (
					<p
						className="text-sm text-rose-700 dark:text-rose-300 m-0 mt-3"
						role="alert"
						data-testid="staff-authority-error"
					>
						{save.message}
					</p>
				) : null}
			</div>
		</article>
	);
};

