				}
			} catch (err: any) {
				console.error("Server STT Error:", err);
				showToast(
					"╨б╨▒╨╛╨╣ ╤Б╨╡╤А╨▓╨╡╤А╨░ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╤П. ╨Я╨╡╤А╨╡╨║╨╗╤О╤З╨░╨╡╨╝ ╨╜╨░ ╨▓╨▓╨╛╨┤ ╤В╨╡╨║╤Б╤В╨╛╨╝.",
					"error",
				);
			} finally {
				setIsProcessing(false);
			}
		},
		[context, dashboard, onResult, clinicalAdminSecretSession.trim],
